[Double_t](../ListOfTypes.html#Double_t) [TGeoEltu](../TGeoEltu.html)::[Safety](../TGeoEltu.html#TGeoEltu:Safety "Double_t TGeoEltu::Safety\(Double_t* point,Bool_t in=kTRUE\)")([Double_t](../ListOfTypes.html#Double_t) *point, [Bool_t](../ListOfTypes.html#Bool_t) /*in*/) const
{
// computes the closest distance from given point to this shape, according
// to option. The matching point on the shape is stored in spoint.
[Double_t](../ListOfTypes.html#Double_t) x0 = [TMath](../TMath.html)::[Abs](../TMath.html#TMath:Abs "Short_t TMath::Abs\(Short_t d\) or overloads")(point[0]);
[Double_t](../ListOfTypes.html#Double_t) y0 = [TMath](../TMath.html)::[Abs](../TMath.html#TMath:Abs "Short_t TMath::Abs\(Short_t d\) or overloads")(point[1]);
[Double_t](../ListOfTypes.html#Double_t) x1, y1, dx, dy;
[Double_t](../ListOfTypes.html#Double_t) safr, safz;
safr = safz = [TGeoShape](../TGeoShape.html)::[Big](../TGeoShape.html#TGeoShape:Big "Double_t TGeoShape::Big\(\)")();
[Double_t](../ListOfTypes.html#Double_t) onepls = 1.+[TGeoShape](../TGeoShape.html)::[Tolerance](../TGeoShape.html#TGeoShape:Tolerance "Double_t TGeoShape::Tolerance\(\)")();
[Double_t](../ListOfTypes.html#Double_t) onemin = 1.-[TGeoShape](../TGeoShape.html)::[Tolerance](../TGeoShape.html#TGeoShape:Tolerance "Double_t TGeoShape::Tolerance\(\)")();
[Double_t](../ListOfTypes.html#Double_t) sqdist = x0*x0/(fRmin*fRmin)+y0*y0/(fRmax*fRmax);
[Bool_t](../ListOfTypes.html#Bool_t) in = [kTRUE](../ListOfTypes.html#Bool_t);
if (sqdist>onepls) in = [kFALSE](../ListOfTypes.html#Bool_t);
else if (sqdist<onemin) in = [kTRUE](../ListOfTypes.html#Bool_t);
else return 0.;

