void [TGeoEltu](../TGeoEltu.html)::[ComputeNormal](../TGeoEltu.html#TGeoEltu:ComputeNormal "void TGeoEltu::ComputeNormal\(Double_t* point,Double_t* dir,Double_t* norm\)")([Double_t](../ListOfTypes.html#Double_t) *point, [Double_t](../ListOfTypes.html#Double_t) *dir, [Double_t](../ListOfTypes.html#Double_t) *norm)
{
// Compute normal to closest surface from POINT.
[Double_t](../ListOfTypes.html#Double_t) a = fRmin;
[Double_t](../ListOfTypes.html#Double_t) b = fRmax;
[Double_t](../ListOfTypes.html#Double_t) eps = [TMath](../TMath.html)::[Sqrt](../TMath.html#TMath:Sqrt "Double_t TMath::Sqrt\(Double_t x\)")(point[0]*point[0]/(a*a)+point[1]*point[1]/(b*b))-1.;
if (eps<1E-4 && [TMath](../TMath.html)::[Abs](../TMath.html#TMath:Abs "Short_t TMath::Abs\(Short_t d\) or overloads")(fDz-[TMath](../TMath.html)::[Abs](../TMath.html#TMath:Abs "Short_t TMath::Abs\(Short_t d\) or overloads")(point[2]))<1E-5) {
norm[0] = norm[1] = 0;
norm[2] = [TMath](../TMath.html)::[Sign](../TMath.html#TMath:Sign "Short_t TMath::Sign\(Short_t a,Short_t b\) or overloads")(1.,dir[2]);
return;
}
norm[2] = 0.;
[Double_t](../ListOfTypes.html#Double_t) r = [TMath](../TMath.html)::[Sqrt](../TMath.html#TMath:Sqrt "Double_t TMath::Sqrt\(Double_t x\)")(point[0]*point[0]+point[1]*point[1]);
[Double_t](../ListOfTypes.html#Double_t) st = point[1]/r;
[Double_t](../ListOfTypes.html#Double_t) ct = point[0]/r;
[Double_t](../ListOfTypes.html#Double_t) rr = [TMath](../TMath.html)::[Sqrt](../TMath.html#TMath:Sqrt "Double_t TMath::Sqrt\(Double_t x\)")(b*b*ct*ct+a*a*st*st);
norm[0] = b*ct/rr;
norm[1] = a*st/rr;
if (norm[0]*dir[0]+norm[1]*dir[1]<0) {
norm[0] = -norm[0];
norm[1] = -norm[1];
}
}

